#!/usr/bin/env sh
# Prints the release notes for a tag, generated by git-cliff from the commits
# since the previous release (see cliff.toml), followed by how to pull the
# matching Docker image. CI uses this as the GitLab release description.
#
# Preview the notes for a release before tagging it (needs git-cliff, e.g.
# `brew install git-cliff`):
#   scripts/release-notes.sh v0.1.0
set -eu

tag=${1:?usage: release-notes.sh <tag> [image]}
image=${2:-}

if ! command -v git-cliff >/dev/null; then
  echo "git-cliff is not installed: brew install git-cliff" >&2
  exit 1
fi

# The range is passed explicitly rather than with --current or --latest: CI
# checks tags out on a detached HEAD, where --current fails, and --latest
# finds nothing for the first release.
if git rev-parse -q --verify "refs/tags/$tag" >/dev/null; then
  end=$tag
  set --
else
  # Not tagged yet: preview HEAD as if it were.
  end=HEAD
  set -- --tag "$tag"
fi

# The previous release, skipping pre-releases so v1.2.0 lists everything since
# v1.1.0 even if v1.2.0-rc.1 came in between. None for the first release.
if prev=$(git describe --tags --abbrev=0 --match 'v[0-9]*' --exclude '*-*' "$end^" 2>/dev/null); then
  set -- "$@" "$prev..$end"
elif [ "$(git rev-parse "$end")" != "$(git rev-parse HEAD)" ]; then
  echo "To preview the first release, check out $tag first." >&2
  exit 1
fi

notes=$(git-cliff --config cliff.toml "$@")

if [ -z "$(printf '%s' "$notes" | tr -d '[:space:]')" ]; then
  echo "No releasable commits for $tag since ${prev:-the first commit}: they are all" >&2
  echo "chore/ci/docs/test/style/build/refactor, which cliff.toml leaves out." >&2
  exit 1
fi

# Drop leading and trailing blank lines, and collapse runs of them.
printf '%s\n' "$notes" | awk 'NF { if (seen && gap) print ""; print; seen = 1; gap = 0; next } { gap = 1 }'
if [ -n "$image" ]; then
  printf '\n### Docker image\n\n```sh\ndocker pull %s\n```\n' "$image"
fi
